                var json = gson.fromJson("{\"jsonrpc\":\"2.0\",\"method\":\"test\",\"params\":{}}", JsonObject.class);
                assertEquals(json, gson.fromJson(client.getRequest(), JsonObject.class));
            }
    };

    assertAll(cases);
}

